def flatten_list(nested: list) -> list:
    """Recursively flatten an arbitrarily nested list of integers."""
    flat = []
    for item in nested:
        if isinstance(item, list):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat
```

