def merge_sorted(arr1: list[int], arr2: list[int]) -> list[int]:
    i = j = 0
    res = []
    n, m = len(arr1), len(arr2)
    while i < n and j < m:
        if arr1[i] <= arr2[j]:
            res.append(arr1[i])
            i += 1
        else:
            res.append(arr2[j])
            j += 1
    if i < n:
        res.extend(arr1[i:])
    if j < m:
        res.extend(arr2[j:])
    return res
```

